typedef struct Edge {
    int to, id;
    struct Edge *next;
} Edge;

Edge *adj[MAXN];
int deg[MAXN];
int color[MAXN];
int max_deg;

void add_edge(int u, int v, int id) {
    Edge *e = (Edge*)malloc(sizeof(Edge));
    e->to = v;
    e->id = id;
    e->next = adj[u];
    adj[u] = e;
}

void dfs(int u, int parent, int parent_color) {
    int c = 1;
    for (Edge *e = adj[u]; e; e = e->next) {
        int v = e->to;
        if (v == parent) continue;
        if (c == parent_color) c++;
        color[e->id] = c;
        dfs(v, u, c);
        c++;
    }
}

