int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *a = (int *)malloc((N - 1) * sizeof(int));
    int *b = (int *)malloc((N - 1) * sizeof(int));
    int *deg = (int *)calloc(N + 1, sizeof(int));

    for (int i = 0; i < N - 1; i++) {
        scanf("%d %d", &a[i], &b[i]);
        deg[a[i]]++;
        deg[b[i]]++;
    }

    int max_deg = 0;
    for (int i = 1; i <= N; i++) {
        if (deg[i] > max_deg) max_deg = deg[i];
    }

    int *head = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    Edge *edges = (Edge *)malloc(2 * (N - 1) * sizeof(Edge));
    int ecnt = 0;
    for (int i = 0; i < N - 1; i++) {
        edges[ecnt].to = b[i];
        edges[ecnt].id = i;
        edges[ecnt].next = head[a[i]];
        head[a[i]] = ecnt++;

        edges[ecnt].to = a[i];
        edges[ecnt].id = i;
        edges[ecnt].next = head[b[i]];
        head[b[i]] = ecnt++;
    }

    int *parent = (int *)malloc((N + 1) * sizeof(int));
    int *parent_color = (int *)malloc((N + 1) * sizeof(int));
    int *visited = (int *)calloc(N + 1, sizeof(int));
    int *queue = (int *)malloc((N + 5) * sizeof(int));
    int *ans = (int *)malloc((N - 1) * sizeof(int));

    int front = 0, back = 0;
    queue[back++] = 1;
    visited[1] = 1;
    parent[1] = 0;
    parent_color[1] = 0;

    while (front < back) {
        int v = queue[front++];
        int color = 1;

        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            int id = edges[e].id;
            if (visited[u]) continue;

            if (color == parent_color[v]) color++;
            ans[id] = color;

            visited[u] = 1;
            parent[u] = v;
            parent_color[u] = color;
            queue[back++] = u;

            color++;
        }
    }

    printf("%d\n", max_deg);
    for (int i = 0; i < N - 1; i++) {
        printf("%d\n", ans[i]);
    }

    free(a);
    free(b);
    free(deg);
    free(head);
    free(edges);
    free(parent);
    free(parent_color);
    free(visited);
    free(queue);
    free(ans);

    return 0;
}

