        adj[a].push_back({b, i});
        adj[b].push_back({a, i});
    }

    // Find max degree
    int maxDeg = 0;
    for (int v = 1; v <= n; v++) {
        maxDeg = max(maxDeg, (int)adj[v].size());
    }

    vector<int> color(n-1, 0);

    // BFS from root = 1
    // parent_color[v] = color of edge from parent to v
    vector<int> parent_color(n+1, 0);
    vector<bool> visited(n+1, false);

    queue<int> q;
    q.push(1);
    visited[1] = true;

    while (!q.empty()) {
        int v = q.front(); q.pop();

        int pc = parent_color[v]; // color used by parent edge
        int c = 1;

        for (auto [u, idx] : adj[v]) {
            if (visited[u]) continue; // skip parent

            // assign color c to edge idx, skipping pc
            if (c == pc) c++;
            color[idx] = c;
            parent_color[u] = c;
            c++;

            visited[u] = true;
            q.push(u);
        }
    }

    cout << maxDeg << "\n";
    for (int i = 0; i < n-1; i++) {
        cout << color[i] << "\n";
    }

