public class Main {
    static List<int[]>[] adj; // adj[v] = list of {neighbor, edge_index}
    static int[] edgeColor;
    static int maxDeg;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        adj = new List[n + 1];
        for (int i = 1; i <= n; i++) adj[i] = new ArrayList<>();

        int[] ea = new int[n - 1];
        int[] eb = new int[n - 1];

        for (int i = 0; i < n - 1; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            ea[i] = a; eb[i] = b;
            adj[a].add(new int[]{b, i});
            adj[b].add(new int[]{a, i});
        }

        // Compute max degree
        maxDeg = 0;
        for (int i = 1; i <= n; i++) {
            maxDeg = Math.max(maxDeg, adj[i].size());
        }

        edgeColor = new int[n - 1];
        Arrays.fill(edgeColor, -1);

        if (n == 1) {
            // No edges
            System.out.println(0);
            return;
        }

        // BFS/DFS from root = 1
        // For each node, assign colors to edges to children
        // avoiding the color used by edge to parent
        int[] parentEdge = new int[n + 1];
        Arrays.fill(parentEdge, -1);

        int[] queue = new int[n + 1];
        boolean[] visited = new boolean[n + 1];
        int head = 0, tail = 0;
        queue[tail++] = 1;
        visited[1] = true;

        while (head < tail) {
            int v = queue[head++];
            int parentColor = (parentEdge[v] == -1) ? -1 : edgeColor[parentEdge[v]];

            // Assign colors to edges to children
            int colorToAssign = 1;
            for (int[] nb : adj[v]) {
                int u = nb[0];
                int eidx = nb[1];
                if (!visited[u]) {
                    // This is a child edge
                    // Skip color used by parent edge
                    if (colorToAssign == parentColor) colorToAssign++;
                    edgeColor[eidx] = colorToAssign;
                    colorToAssign++;
                    visited[u] = true;
                    parentEdge[u] = eidx;
                    queue[tail++] = u;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append(maxDeg).append('\n');
        for (int i = 0; i < n - 1; i++) {
            sb.append(edgeColor[i]).append('\n');
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class Edge {
        int to, idx;
        Edge(int to, int idx) {
            this.to = to;
            this.idx = idx;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();

        List<Edge>[] g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();

        int[] a = new int[N - 1];
        int[] b = new int[N - 1];
        int[] deg = new int[N + 1];

        for (int i = 0; i < N - 1; i++) {
            a[i] = fs.nextInt();
            b[i] = fs.nextInt();
            g[a[i]].add(new Edge(b[i], i));
            g[b[i]].add(new Edge(a[i], i));
            deg[a[i]]++;
            deg[b[i]]++;
        }

        int maxDegree = 0;
        for (int i = 1; i <= N; i++) maxDegree = Math.max(maxDegree, deg[i]);

        int[] ans = new int[N - 1];
        boolean[] visited = new boolean[N + 1];

        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{1, 0}); // {current node, color used by edge from parent}
        visited[1] = true;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int v = cur[0];
            int parentColor = cur[1];

            int color = 1;
            for (Edge e : g[v]) {
                if (visited[e.to]) continue;
                if (color == parentColor) color++;
                ans[e.idx] = color;
                visited[e.to] = true;
                q.add(new int[]{e.to, color});
                color++;
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append(maxDegree).append('\n');
        for (int i = 0; i < N - 1; i++) {
            sb.append(ans[i]).append('\n');
        }
        System.out.print(sb.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
